-- PRODUCT_seed.csv -> 기존 product row UPDATE
-- 매칭 키: name (정확 일치). 미매칭은 INSERT하지 않고 리포트만 남김.
-- description / storage_score / versatility_score /
-- travel_suitability_score / commute_suitability_score 는 덮어쓰지 않음.
-- sku NOT NULL 은 미매칭이 없을 때만 적용.

BEGIN;

CREATE TEMP TABLE product_seed (
    sku VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    category VARCHAR(255),
    price BIGINT,
    image_url VARCHAR(255),
    detail_url TEXT,
    description TEXT,
    product_feature TEXT,
    care_guide TEXT,
    storage_score INTEGER,
    versatility_score INTEGER,
    travel_suitability_score INTEGER,
    commute_suitability_score INTEGER,
    laptop_storage_available BOOLEAN,
    laptop_storage_score INTEGER,
    cabin_suitability_score INTEGER,
    active BOOLEAN,
    source_collected_at DATE
) ON COMMIT DROP;

INSERT INTO product_seed (
    sku, name, category, price, image_url, detail_url, description,
    product_feature, care_guide, storage_score, versatility_score,
    travel_suitability_score, commute_suitability_score,
    laptop_storage_available, laptop_storage_score, cabin_suitability_score,
    active, source_collected_at
) VALUES
    ('MMKGATA03MT001', 'M Aren 노바 나일론 백팩', '가방', 1450000, 'https://lounge-backend-bucket.s3.ap-northeast-2.amazonaws.com/bags/MMKGATA03MT001.jpg', 'https://kr.mcmworldwide.com/ko_KR/%EB%82%A8%EC%84%B1/%EA%B0%80%EB%B0%A9/%EB%B0%B1%ED%8C%A9/aren-%EB%85%B8%EB%B0%94-%EB%82%98%EC%9D%BC%EB%A1%A0-%EB%B0%B1%ED%8C%A9/MMKGATA03MT001.html', 'M Aren 노바 나일론 백팩은 가볍게 들기 좋은 패브릭 계열 바디 · 두 손을 자유롭게 쓰는 백팩 구조 · 일상 수납과 휴대성의 균형이 제품의 성격을 분명하게 보여주는 가방입니다. 노트·파우치·물병처럼 무게가 다른 물건을 나눠 담고 두 손을 비워야 하는 출퇴근·통학에 잘 맞습니다. 무거운 물건은 등판 가까이에 두면 이동 중 무게가 덜 흔들립니다.', 'M Aren 노바 나일론 백팩: 가볍게 들기 좋은 패브릭 계열 바디 · 두 손을 자유롭게 쓰는 백팩 구조 · 일상 수납과 휴대성의 균형', 'M Aren 노바 나일론 백팩 관리: 표면 먼지는 부드러운 솔로 결을 따라 털고, 물기가 묻으면 문지르지 말고 마른 천으로 눌러 흡수한 뒤 자연 건조하세요. 보관할 때는 내부를 가볍게 채워 형태를 잡고 통풍되는 더스트백을 사용하세요.', 4, 5, 5, 5, TRUE, 4, 4, TRUE, '2026-08-16'::date),
    ('MMKGATA02BK001', 'M Aren 노바 모노그램 ECONYL® 백팩', '가방', 1450000, 'https://lounge-backend-bucket.s3.ap-northeast-2.amazonaws.com/bags/MMKGATA02BK001.jpg', 'https://kr.mcmworldwide.com/ko_KR/%EB%82%A8%EC%84%B1/%EA%B0%80%EB%B0%A9/%EB%B0%B1%ED%8C%A9/aren-%EB%85%B8%EB%B0%94-%EB%AA%A8%EB%85%B8%EA%B7%B8%EB%9E%A8-econyl%C2%AE-%EB%B0%B1%ED%8C%A9/MMKGATA02BK001.html', 'M Aren 노바 모노그램 ECONYL® 백팩은 가볍게 들기 좋은 패브릭 계열 바디 · 입체감 있는 모노그램 표현 · 두 손을 자유롭게 쓰는 백팩 구조 · 일상 수납과 휴대성의 균형이 제품의 성격을 분명하게 보여주는 가방입니다. 노트·파우치·물병처럼 무게가 다른 물건을 나눠 담고 두 손을 비워야 하는 출퇴근·통학에 잘 맞습니다. 무거운 물건은 등판 가까이에 두면 이동 중 무게가 덜 흔들립니다.', 'M Aren 노바 모노그램 ECONYL® 백팩: 가볍게 들기 좋은 패브릭 계열 바디 · 입체감 있는 모노그램 표현 · 두 손을 자유롭게 쓰는 백팩 구조 · 일상 수납과 휴대성의 균형', 'M Aren 노바 모노그램 ECONYL® 백팩 관리: 표면 먼지는 부드러운 솔로 결을 따라 털고, 물기가 묻으면 문지르지 말고 마른 천으로 눌러 흡수한 뒤 자연 건조하세요. 보관할 때는 내부를 가볍게 채워 형태를 잡고 통풍되는 더스트백을 사용하세요.', 4, 5, 5, 5, TRUE, 4, 4, TRUE, '2026-08-16'::date),
    ('MMTGATA03BK001', 'S–M Aren 노바 나일론 토트', '가방', 990000, 'https://lounge-backend-bucket.s3.ap-northeast-2.amazonaws.com/bags/MMTGATA03BK001.jpg', 'https://kr.mcmworldwide.com/ko_KR/%EB%82%A8%EC%84%B1/%EA%B0%80%EB%B0%A9/%ED%86%A0%ED%8A%B8%EB%B0%B1/aren-%EB%85%B8%EB%B0%94-%EB%82%98%EC%9D%BC%EB%A1%A0-%ED%86%A0%ED%8A%B8/MMTGATA03BK001.html', 'S–M Aren 노바 나일론 토트는 가볍게 들기 좋은 패브릭 계열 바디 · 넓은 입구로 물건을 빠르게 넣고 빼는 토트·쇼퍼 구조 · 일상 수납과 휴대성의 균형이 제품의 성격을 분명하게 보여주는 가방입니다. 노트·파우치·물병을 한 번에 챙기는 출근이나 통학 동선에 유용합니다. 무거운 물건을 한쪽에 몰지 않고 세로로 나눠 담으면 형태와 균형을 유지하기 좋습니다.', 'S–M Aren 노바 나일론 토트: 가볍게 들기 좋은 패브릭 계열 바디 · 넓은 입구로 물건을 빠르게 넣고 빼는 토트·쇼퍼 구조 · 일상 수납과 휴대성의 균형', 'S–M Aren 노바 나일론 토트 관리: 표면 먼지는 부드러운 솔로 결을 따라 털고, 물기가 묻으면 문지르지 말고 마른 천으로 눌러 흡수한 뒤 자연 건조하세요. 보관할 때는 내부를 가볍게 채워 형태를 잡고 통풍되는 더스트백을 사용하세요.', 4, 5, 4, 5, TRUE, 4, 4, TRUE, '2026-08-16'::date),
    ('MMRGATA07BK001', 'S Aren 노바 모노그램 ECONYL® 크로스바디', '가방', 1090000, 'https://lounge-backend-bucket.s3.ap-northeast-2.amazonaws.com/bags/MMRGATA07BK001.jpg', 'https://kr.mcmworldwide.com/ko_KR/%EB%82%A8%EC%84%B1/%EA%B0%80%EB%B0%A9/%ED%81%AC%EB%A1%9C%EC%8A%A4%EB%B0%B1/aren-%EB%85%B8%EB%B0%94-%EB%AA%A8%EB%85%B8%EA%B7%B8%EB%9E%A8-econyl%C2%AE-%ED%81%AC%EB%A1%9C%EC%8A%A4%EB%B0%94%EB%94%94/MMRGATA07BK001.html', 'S Aren 노바 모노그램 ECONYL® 크로스바디는 가볍게 들기 좋은 패브릭 계열 바디 · 입체감 있는 모노그램 표현 · 이동 중 필수품에 빠르게 접근하는 숄더·크로스 구조 · 휴대성을 우선한 작은 비율이 제품의 성격을 분명하게 보여주는 가방입니다. 휴대폰과 지갑을 자주 꺼내면서 두 손을 자유롭게 쓰고 싶은 약속·여행지 산책에 잘 맞습니다. A4 문서나 노트북처럼 납작하고 큰 물건을 챙기는 날에는 토트나 백팩이 더 편합니다.', 'S Aren 노바 모노그램 ECONYL® 크로스바디: 가볍게 들기 좋은 패브릭 계열 바디 · 입체감 있는 모노그램 표현 · 이동 중 필수품에 빠르게 접근하는 숄더·크로스 구조 · 휴대성을 우선한 작은 비율', 'S Aren 노바 모노그램 ECONYL® 크로스바디 관리: 표면 먼지는 부드러운 솔로 결을 따라 털고, 물기가 묻으면 문지르지 말고 마른 천으로 눌러 흡수한 뒤 자연 건조하세요. 보관할 때는 내부를 가볍게 채워 형태를 잡고 통풍되는 더스트백을 사용하세요.', 2, 5, 4, 4, FALSE, 0, 5, TRUE, '2026-08-16'::date),
    ('MMVGATT06BK001', '55cm / 22인치 Aren 노바 모노그램 ECONYL® 위켄더', '가방', 1850000, 'https://lounge-backend-bucket.s3.ap-northeast-2.amazonaws.com/bags/MMVGATT06BK001.jpg', 'https://kr.mcmworldwide.com/ko_KR/%ED%8A%B8%EB%9E%98%EB%B8%94/%EB%9F%AC%EA%B8%B0%EC%A7%80-%EB%B0%B1/aren-%EB%85%B8%EB%B0%94-%EB%AA%A8%EB%85%B8%EA%B7%B8%EB%9E%A8-econyl%C2%AE-%EC%9C%84%EC%BC%84%EB%8D%94/MMVGATT06BK001.html', '55cm / 22인치 Aren 노바 모노그램 ECONYL® 위켄더는 가볍게 들기 좋은 패브릭 계열 바디 · 입체감 있는 모노그램 표현 · 의류와 파우치를 나누기 좋은 여행용 수납 구조 · 여행 짐까지 고려한 큰 비율이 제품의 성격을 분명하게 보여주는 가방입니다. 의류·세면 파우치·전자기기를 구역별로 나눠야 하는 주말여행이나 항공 이동에 잘 맞습니다. 일상용으로는 부피가 크게 느껴질 수 있어 여행 중심 사용자에게 더 적합합니다.', '55cm / 22인치 Aren 노바 모노그램 ECONYL® 위켄더: 가볍게 들기 좋은 패브릭 계열 바디 · 입체감 있는 모노그램 표현 · 의류와 파우치를 나누기 좋은 여행용 수납 구조 · 여행 짐까지 고려한 큰 비율', '55cm / 22인치 Aren 노바 모노그램 ECONYL® 위켄더 관리: 표면 먼지는 부드러운 솔로 결을 따라 털고, 물기가 묻으면 문지르지 말고 마른 천으로 눌러 흡수한 뒤 자연 건조하세요. 보관할 때는 내부를 가볍게 채워 형태를 잡고 통풍되는 더스트백을 사용하세요.', 5, 3, 5, 3, FALSE, 0, 3, TRUE, '2026-08-16'::date),
