-- CSV name 미매칭 (신규 INSERT 하지 않음)
SELECT s.sku, s.name AS unmatched_csv_name
FROM product_seed s
LEFT JOIN product p ON p.name = s.name
WHERE p.id IS NULL
ORDER BY s.name;

-- 기존 컬럼이 CSV와 다르면 로그만 (덮어쓰지 않음)
SELECT
    p.id,
    p.name,
    CASE WHEN p.description IS DISTINCT FROM s.description THEN 'description' END AS description_diff,
    CASE WHEN p.storage_score IS DISTINCT FROM s.storage_score THEN 'storage_score' END AS storage_score_diff,
    CASE WHEN p.versatility_score IS DISTINCT FROM s.versatility_score THEN 'versatility_score' END AS versatility_score_diff,
    CASE WHEN p.travel_suitability_score IS DISTINCT FROM s.travel_suitability_score THEN 'travel_suitability_score' END AS travel_suitability_score_diff,
    CASE WHEN p.commute_suitability_score IS DISTINCT FROM s.commute_suitability_score THEN 'commute_suitability_score' END AS commute_suitability_score_diff
FROM product p
JOIN product_seed s ON s.name = p.name
WHERE p.description IS DISTINCT FROM s.description
   OR p.storage_score IS DISTINCT FROM s.storage_score
   OR p.versatility_score IS DISTINCT FROM s.versatility_score
   OR p.travel_suitability_score IS DISTINCT FROM s.travel_suitability_score
   OR p.commute_suitability_score IS DISTINCT FROM s.commute_suitability_score
ORDER BY p.id;

UPDATE product p
SET
    sku = s.sku,
    category = s.category,
    price = s.price,
    image_url = s.image_url,
    detail_url = s.detail_url,
    product_feature = s.product_feature,
    care_guide = s.care_guide,
    laptop_storage_available = s.laptop_storage_available,
    laptop_storage_score = s.laptop_storage_score,
    cabin_suitability_score = s.cabin_suitability_score,
    active = s.active,
    source_collected_at = s.source_collected_at
FROM product_seed s
WHERE p.name = s.name;

SELECT COUNT(*) AS matched_updated_count
FROM product p
JOIN product_seed s ON s.name = p.name;

SELECT id, name AS product_without_sku
FROM product
WHERE sku IS NULL
ORDER BY id;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM product WHERE sku IS NULL) THEN
        RAISE NOTICE 'sku NULL rows remain; skip NOT NULL. Inspect: SELECT id, name FROM product WHERE sku IS NULL;';
    ELSE
        ALTER TABLE product ALTER COLUMN sku SET NOT NULL;
        RAISE NOTICE 'product.sku set to NOT NULL';
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uk_product_sku ON product (sku);

COMMIT;
